const it = $input.first(); const b = it.json.body || {};
const temImagem = !!(it.binary && it.binary.imagem);
const descricao = typeof b.descricao === 'string' ? b.descricao.trim() : '';
// Upload de cadastro (Cadastro de Produtos): tipo=produtos + texto e/ou imagem. Qualquer outra chamada = geração de atributos (comportamento anterior).
const cadastrar = String(b.tipo || '') === 'produtos' && (descricao.length > 0 || temImagem);
return [{ json: { cadastrar, descricao, body: b }, binary: it.binary }];

// Função genuinamente nova — geração/inferência não existe em nenhum
// workflow atual (gerenciar_cadastro só grava o que já vem pronto).
const system_prompt = 'Você sugere atributos de catálogo pra um produto de '
 + 'e-commerce brasileiro, a partir dos dados que o lojista já digitou. '
 + 'Responda APENAS com um objeto JSON: {"categoria": string|null, "ncm": '
 + 'string|null (formato 0000.00.00), "preco": string|null (formato "R$ 00,00"), '
 + '"justificativa": string|null}. Para cada atributo, só preencha um valor se '
 + 'os dados fornecidos derem base real pra isso. Se não houver informação '
 + 'suficiente pra um atributo, retorne null nesse atributo — NUNCA invente ou '
 + 'estime um valor sem base nos dados. Quando qualquer atributo vier null, '
 + 'preencha "justificativa" com uma frase curta dizendo o que falta pra '
 + 'estimar (ex.: "sem categoria ou palavras-chave do produto, não é possível '
 + 'sugerir NCM nem preço"). Dado desconhecido é uma resposta válida.';
const gemini = { system_instruction: { parts: [{ text: system_prompt }] },
  contents: [{ role: 'user', parts: [{ text: JSON.stringify($json.body || {}) }] }],
  generationConfig: { response_mime_type: 'application/json' } };
return [{ json: { gemini } }];

const resp = $input.first().json;
let atributos = { categoria: null, ncm: null, preco: null, justificativa: null };
try {
  const texto = resp.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  const parsed = JSON.parse(texto);
  // Só aceita o que veio de fato — não troca null por '' nem inventa default.
  atributos = { categoria: parsed.categoria ?? null, ncm: parsed.ncm ?? null, preco: parsed.preco ?? null, justificativa: parsed.justificativa ?? null };
} catch (e) { atributos.justificativa = 'Não foi possível interpretar a resposta da Lyra agora'; }
return [{ json: { status: 200, body: atributos } }];

const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];

const falta = ['GEMINI_API_KEY', 'ERPNEXT_DOMAIN', 'ERPNEXT_API_KEY', 'ERPNEXT_API_SECRET'].filter(k => !$env[k]);
if (falta.length) return fail(500, 'PENDENTE_CONFIGURACAO: variáveis ausentes no Harmonia: ' + falta.join(', '), 'PENDENTE_CONFIGURACAO');
const it = $input.first(); const descricao = it.json.descricao || '';
const parts = [];
if (descricao) parts.push({ text: 'Descrição enviada pelo lojista: ' + descricao });
if (it.binary && it.binary.imagem) {
  const bin = it.binary.imagem;
  if (!String(bin.mimeType || '').startsWith('image/')) return fail(400, 'O arquivo enviado não é uma imagem');
  const buf = await this.helpers.getBinaryDataBuffer(0, 'imagem');
  if (buf.length > 15 * 1024 * 1024) return fail(413, 'Imagem acima de 15 MB');
  parts.push({ inline_data: { mime_type: bin.mimeType, data: buf.toString('base64') } });
}
if (!parts.length) return fail(400, 'Envie texto e/ou imagem do produto');
const system = 'Você extrai dados de cadastro de UM produto a partir de texto e/ou imagem (foto, embalagem, nota fiscal). '
 + 'Responda APENAS com um objeto JSON: {"item_name": string|null, "item_code": string|null (SKU/código de barras/código impresso, só se aparecer), '
 + '"standard_rate": number|null (preço de venda, só se aparecer), "description": string|null, "categoria": string|null, "ncm": string|null (0000.00.00, só se houver base real), "marca": string|null}. '
 + 'NUNCA invente valor sem base no material enviado: dado ausente = null.';
const gemini = { system_instruction: { parts: [{ text: system }] }, contents: [{ role: 'user', parts }], generationConfig: { response_mime_type: 'application/json' } };
return [{ json: { ok: true, gemini } }];

const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];

let x = {};
try { x = JSON.parse($input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '{}'); } catch (e) { return fail(422, 'A Lyra não conseguiu interpretar o material enviado'); }
const nome = typeof x.item_name === 'string' ? x.item_name.trim() : '';
if (!nome) return fail(422, 'A Lyra não identificou o nome do produto no material enviado');
const slug = (s) => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40);
const codigoMaterial = typeof x.item_code === 'string' ? x.item_code.trim().replace(/[^A-Za-z0-9._-]/g, '') : '';
const item_code = codigoMaterial || slug(nome);
if (!item_code) return fail(422, 'Não foi possível derivar um código para o produto');
const item = { item_code, item_name: nome.slice(0, 140), item_group: 'All Item Groups', stock_uom: 'Nos' };
const preco = Number(x.standard_rate); if (Number.isFinite(preco) && preco > 0) item.standard_rate = preco;
if (typeof x.description === 'string' && x.description.trim()) item.description = x.description.trim();
return [{ json: { ok: true, item, sugestoes: { categoria: x.categoria ?? null, ncm: x.ncm ?? null, marca: x.marca ?? null } } }];

const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];

const r = $input.first().json; const m = $('Monta Item').first().json;
if (r.statusCode === 404) return [{ json: { ok: true, item: m.item, sugestoes: m.sugestoes } }];
if (r.statusCode === 200) return fail(409, 'Já existe um produto com o código ' + m.item.item_code + ' no Ritmo — nada foi criado', 'ITEM_JA_EXISTE');
return fail(502, 'Falha ao consultar o Ritmo antes de criar o produto (HTTP ' + r.statusCode + ')');

const r = $input.first().json; const d = $('Decide criação').first().json;
const doc = r.body && r.body.data;
if (r.statusCode === 200 && doc && doc.item_code === d.item.item_code) {
  return [{ json: { status: 200, body: { sucesso: true, item_code: doc.item_code, item_name: doc.item_name, resumo: 'Produto "' + doc.item_name + '" cadastrado no Ritmo (código ' + doc.item_code + ')', sugestoes: d.sugestoes } } }];
}
const m = 'O Item não foi encontrado no Ritmo após a criação — cadastro NÃO confirmado';
return [{ json: { status: 502, body: { sucesso: false, erro: m, message: m } } }];

const it = $input.first().json || {};
const e = it.error || it;
const raw = String(e.description || e.message || 'erro desconhecido');
const upstream = Number(e.httpCode || e.statusCode || e.status || (e.cause && e.cause.status) || 0);
const clean = raw.replace(/https?:\/\/\S+/g, '[url]').replace(/(token|api_access_token|authorization)\S*/gi, '[omitido]').slice(0, 300);
const status = upstream === 404 ? 404 : 502;
const m = "Falha no cadastro do produto" + (upstream ? ' (HTTP ' + upstream + ')' : '') + (true ? ': ' + clean : '');
return [{ json: { status, body: { sucesso: false, erro: m, message: m, origem: "lyra-cadastro" } } }];
